//! Synthetic-raster tests: every drawing here is generated by the tiny rasteriser below; no real
//! drawing data is used anywhere.

use std::f64::consts::TAU;

use oe_drawing_pixel::{
    Ink, Pattern, Primitive, Stroke, arrow_tip, calibrate_scale, erase, fit_segment,
    merge_collinear, snap_point, text_box_fit, vectorize,
};

/// Minimal aliasing-free rasteriser writing into a boolean mask.
struct Canvas {
    w: usize,
    h: usize,
    m: Vec<bool>,
}

impl Canvas {
    fn new(w: usize, h: usize) -> Canvas {
        Canvas {
            w,
            h,
            m: vec![false; w * h],
        }
    }

    fn set(&mut self, x: i64, y: i64) {
        if x >= 0 && y >= 0 && (x as usize) < self.w && (y as usize) < self.h {
            self.m[y as usize * self.w + x as usize] = true;
        }
    }

    /// Bresenham line including both endpoints.
    fn line(&mut self, x0: i64, y0: i64, x1: i64, y1: i64) {
        let (dx, dy) = ((x1 - x0).abs(), -(y1 - y0).abs());
        let (sx, sy) = (if x0 < x1 { 1 } else { -1 }, if y0 < y1 { 1 } else { -1 });
        let (mut x, mut y, mut err) = (x0, y0, dx + dy);
        loop {
            self.set(x, y);
            if x == x1 && y == y1 {
                break;
            }
            let e2 = 2 * err;
            if e2 >= dy {
                err += dy;
                x += sx;
            }
            if e2 <= dx {
                err += dx;
                y += sy;
            }
        }
    }

    /// All pixel centres within `w/2` of the segment.
    fn thick_line(&mut self, p: (f64, f64), q: (f64, f64), w: f64) {
        let r = w * 0.5;
        let x0 = (p.0.min(q.0) - r).floor() as i64;
        let x1 = (p.0.max(q.0) + r).ceil() as i64;
        let y0 = (p.1.min(q.1) - r).floor() as i64;
        let y1 = (p.1.max(q.1) + r).ceil() as i64;
        let (ax, ay) = p;
        let (bx, by) = q;
        let l2 = (bx - ax).powi(2) + (by - ay).powi(2);
        for y in y0..=y1 {
            for x in x0..=x1 {
                let (px, py) = (x as f64, y as f64);
                let t = if l2 > 0.0 {
                    (((px - ax) * (bx - ax) + (py - ay) * (by - ay)) / l2).clamp(0.0, 1.0)
                } else {
                    0.0
                };
                let (cx, cy) = (ax + t * (bx - ax), ay + t * (by - ay));
                if (px - cx).hypot(py - cy) <= r + 1e-9 {
                    self.set(x, y);
                }
            }
        }
    }

    /// Dashes of `dash` px separated by `gap` px along the segment (1-px Bresenham strokes).
    fn dashed(&mut self, p: (f64, f64), q: (f64, f64), dash: f64, gap: f64) {
        let len = (q.0 - p.0).hypot(q.1 - p.1);
        let d = ((q.0 - p.0) / len, (q.1 - p.1) / len);
        let mut t = 0.0;
        while t < len - 1e-9 {
            let e = (t + dash).min(len);
            let a = (p.0 + d.0 * t, p.1 + d.1 * t);
            let b = (p.0 + d.0 * e, p.1 + d.1 * e);
            self.line(
                a.0.round() as i64,
                a.1.round() as i64,
                b.0.round() as i64,
                b.1.round() as i64,
            );
            t += dash + gap;
        }
    }

    /// 1-px ring: pixel centres with `| |p - c| - r | <= 0.5`.
    fn circle(&mut self, c: (f64, f64), r: f64) {
        let x0 = (c.0 - r - 1.0).floor() as i64;
        let x1 = (c.0 + r + 1.0).ceil() as i64;
        let y0 = (c.1 - r - 1.0).floor() as i64;
        let y1 = (c.1 + r + 1.0).ceil() as i64;
        for y in y0..=y1 {
            for x in x0..=x1 {
                let d = (x as f64 - c.0).hypot(y as f64 - c.1);
                if (d - r).abs() <= 0.5 {
                    self.set(x, y);
                }
            }
        }
    }

    fn filled_disc(&mut self, c: (f64, f64), r: f64) {
        let x0 = (c.0 - r - 1.0).floor() as i64;
        let x1 = (c.0 + r + 1.0).ceil() as i64;
        let y0 = (c.1 - r - 1.0).floor() as i64;
        let y1 = (c.1 + r + 1.0).ceil() as i64;
        for y in y0..=y1 {
            for x in x0..=x1 {
                if (x as f64 - c.0).hypot(y as f64 - c.1) <= r {
                    self.set(x, y);
                }
            }
        }
    }

    /// Filled triangle by edge functions (pixel centres inside or on the edges).
    fn filled_triangle(&mut self, a: (f64, f64), b: (f64, f64), c: (f64, f64)) {
        let x0 = a.0.min(b.0).min(c.0).floor() as i64;
        let x1 = a.0.max(b.0).max(c.0).ceil() as i64;
        let y0 = a.1.min(b.1).min(c.1).floor() as i64;
        let y1 = a.1.max(b.1).max(c.1).ceil() as i64;
        let edge = |p: (f64, f64), q: (f64, f64), x: f64, y: f64| {
            (q.0 - p.0) * (y - p.1) - (q.1 - p.1) * (x - p.0)
        };
        let area = edge(a, b, c.0, c.1);
        for y in y0..=y1 {
            for x in x0..=x1 {
                let (px, py) = (x as f64, y as f64);
                let (e0, e1, e2) = (edge(a, b, px, py), edge(b, c, px, py), edge(c, a, px, py));
                let inside = if area >= 0.0 {
                    e0 >= -1e-9 && e1 >= -1e-9 && e2 >= -1e-9
                } else {
                    e0 <= 1e-9 && e1 <= 1e-9 && e2 <= 1e-9
                };
                if inside {
                    self.set(x, y);
                }
            }
        }
    }

    fn filled_rect(&mut self, x0: i64, y0: i64, x1: i64, y1: i64) {
        for y in y0..=y1 {
            for x in x0..=x1 {
                self.set(x, y);
            }
        }
    }

    fn ink(&self) -> Ink {
        Ink::from_mask(self.w, self.h, self.m.clone())
    }
}

fn dist(a: (f64, f64), b: (f64, f64)) -> f64 {
    (a.0 - b.0).hypot(a.1 - b.1)
}

/// A line stroke whose endpoints match `a`–`b` (either orientation) within `tol`.
fn find_line(strokes: &[Stroke], a: (f64, f64), b: (f64, f64), tol: f64) -> Option<&Stroke> {
    strokes.iter().find(|s| match s.primitive {
        Primitive::Line { p, q } => {
            (dist(p, a) <= tol && dist(q, b) <= tol) || (dist(p, b) <= tol && dist(q, a) <= tol)
        }
        Primitive::Arc { .. } => false,
    })
}

fn arcs(strokes: &[Stroke]) -> Vec<&Stroke> {
    strokes
        .iter()
        .filter(|s| matches!(s.primitive, Primitive::Arc { .. }))
        .collect()
}

#[test]
fn fit_segment_recovers_exact_line() {
    let mut c = Canvas::new(240, 160);
    c.line(20, 30, 170, 80);
    let ink = c.ink();
    let fit = fit_segment(&ink, (20.0, 30.0), (170.0, 80.0), 3.0, 2.0);
    assert!(dist(fit.p, (20.0, 30.0)) < 0.3, "p = {:?}", fit.p);
    assert!(dist(fit.q, (170.0, 80.0)) < 0.3, "q = {:?}", fit.q);
    assert!(
        fit.support_before > 0.98,
        "support_before = {}",
        fit.support_before
    );
    assert!(
        fit.support_after > 0.98,
        "support_after = {}",
        fit.support_after
    );
    assert!(fit.moved_px < 0.3, "moved = {}", fit.moved_px);
    assert!(
        (0.5..=2.0).contains(&fit.width_px),
        "width = {}",
        fit.width_px
    );
}

#[test]
fn fit_segment_corrects_offset_short_proposal() {
    let mut c = Canvas::new(260, 200);
    c.line(30, 120, 230, 120);
    let ink = c.ink();
    // Proposal: 3 px off the stroke and 10 % short at each end.
    let fit = fit_segment(&ink, (50.0, 123.0), (210.0, 123.0), 5.0, 2.0);
    assert!(fit.moved_px > 10.0, "moved = {}", fit.moved_px);
    assert!(dist(fit.p, (30.0, 120.0)) < 0.5, "p = {:?}", fit.p);
    assert!(dist(fit.q, (230.0, 120.0)) < 0.5, "q = {:?}", fit.q);
    assert!(
        fit.support_before < 0.2,
        "support_before = {}",
        fit.support_before
    );
    assert!(
        fit.support_after > 0.98,
        "support_after = {}",
        fit.support_after
    );
    assert!(
        (0.5..=2.0).contains(&fit.width_px),
        "width = {}",
        fit.width_px
    );
}

#[test]
fn fit_segment_measures_thick_stroke_width() {
    let mut c = Canvas::new(200, 100);
    c.thick_line((20.0, 50.0), (180.0, 50.0), 3.0);
    let ink = c.ink();
    let fit = fit_segment(&ink, (22.0, 51.0), (178.0, 49.5), 4.0, 2.0);
    assert!(
        (2.5..=3.5).contains(&fit.width_px),
        "width = {}",
        fit.width_px
    );
    // The round caps of a width-3 stroke put ink at x = 19 and x = 181; the fit reports the ink.
    assert!(dist(fit.p, (19.0, 50.0)) < 0.6, "p = {:?}", fit.p);
    assert!(dist(fit.q, (181.0, 50.0)) < 0.6, "q = {:?}", fit.q);
}

#[test]
fn fit_segment_without_ink_returns_proposal_unchanged() {
    let ink = Canvas::new(100, 100).ink();
    let fit = fit_segment(&ink, (10.0, 10.0), (90.0, 40.0), 4.0, 2.0);
    assert_eq!(fit.p, (10.0, 10.0));
    assert_eq!(fit.q, (90.0, 40.0));
    assert_eq!(fit.support_before, 0.0);
    assert_eq!(fit.support_after, 0.0);
    assert_eq!(fit.moved_px, 0.0);
    assert_eq!(fit.width_px, 0.0);
}

#[test]
fn fit_segment_bridges_gaps_only_up_to_max_gap() {
    let mut c = Canvas::new(260, 200);
    // Dashes 20..=30, 34..=44, ... with three empty pixels between them.
    c.dashed((20.0, 100.0), (220.0, 100.0), 10.0, 4.0);
    let ink = c.ink();
    let short = fit_segment(&ink, (20.0, 100.0), (30.0, 100.0), 3.0, 2.0);
    assert!(dist(short.q, (30.0, 100.0)) < 0.3, "q = {:?}", short.q);
    let long = fit_segment(&ink, (20.0, 100.0), (30.0, 100.0), 3.0, 5.0);
    assert!(dist(long.q, (220.0, 100.0)) < 0.3, "q = {:?}", long.q);
    assert!(dist(long.p, (20.0, 100.0)) < 0.3, "p = {:?}", long.p);
    // The bridged gaps are honestly reported as missing support.
    assert!(
        long.support_after > 0.6 && long.support_after < 0.95,
        "support = {}",
        long.support_after
    );
}

#[test]
fn snap_point_returns_nearest_dark_pixel() {
    let mut c = Canvas::new(50, 50);
    c.set(20, 20);
    c.set(30, 30);
    let ink = c.ink();
    assert_eq!(snap_point(&ink, (22.0, 21.0), 5.0), Some((20.0, 20.0)));
    assert_eq!(snap_point(&ink, (28.0, 29.0), 5.0), Some((30.0, 30.0)));
    assert_eq!(snap_point(&ink, (10.0, 40.0), 5.0), None);
}

#[test]
fn arrow_tip_finds_triangle_apex() {
    let mut c = Canvas::new(160, 100);
    // Right-pointing arrowhead on a dimension line, apex at (100, 50).
    c.line(40, 50, 88, 50);
    c.filled_triangle((100.0, 50.0), (88.0, 46.0), (88.0, 54.0));
    // Left-pointing arrowhead, apex at (40, 50), on the same line.
    c.filled_triangle((40.0, 50.0), (52.0, 46.0), (52.0, 54.0));
    let ink = c.ink();
    let tip = arrow_tip(&ink, (97.0, 52.0), (1.0, 0.0), 8.0).expect("tip");
    assert!(dist(tip, (100.0, 50.0)) <= 1.0, "tip = {tip:?}");
    let tip = arrow_tip(&ink, (43.0, 48.5), (-1.0, 0.0), 8.0).expect("tip");
    assert!(dist(tip, (40.0, 50.0)) <= 1.0, "tip = {tip:?}");
    assert_eq!(arrow_tip(&ink, (140.0, 20.0), (1.0, 0.0), 6.0), None);
}

#[test]
fn text_box_fit_tightens_to_glyphs_and_ignores_specks() {
    let mut c = Canvas::new(120, 80);
    c.filled_rect(50, 40, 58, 52);
    c.filled_rect(62, 40, 70, 52);
    c.set(80, 45); // isolated speck
    c.set(47, 55);
    c.set(48, 55); // two-pixel speck
    c.line(30, 60, 110, 60); // a stroke passing below the proposed box
    let ink = c.ink();
    let b = text_box_fit(&ink, (45.0, 35.0, 85.0, 57.0), 2.0);
    assert_eq!(b, (50.0, 40.0, 70.0, 52.0));
    // Nothing kept: the proposal comes back unchanged (normalised).
    let empty = text_box_fit(&ink, (10.0, 20.0, 5.0, 10.0), 1.0);
    assert_eq!(empty, (5.0, 10.0, 10.0, 20.0));
}

#[test]
fn erase_clears_stroke_but_keeps_neighbours() {
    let mut c = Canvas::new(100, 100);
    c.line(10, 50, 90, 50);
    c.line(50, 10, 50, 90);
    let mut ink = c.ink();
    let before = ink.dark_count();
    erase(&mut ink, &[((10.0, 50.0), (90.0, 50.0), 1.0)], &[]);
    assert!(!ink.is_dark(30, 50));
    assert!(
        ink.is_dark(50, 49) && ink.is_dark(50, 51),
        "crossing stroke survives"
    );
    assert_eq!(before - ink.dark_count(), 81);
    erase(&mut ink, &[], &[(45.0, 10.0, 55.0, 30.0)]);
    assert!(!ink.is_dark(50, 20) && ink.is_dark(50, 31));
}

/// Drawing shared by the vectorisation tests: two lines, a dashed line, a circle and a filled blob.
fn drawing() -> Canvas {
    let mut c = Canvas::new(300, 220);
    c.line(20, 20, 220, 20);
    c.line(30, 40, 130, 150);
    c.dashed((20.0, 190.0), (280.0, 190.0), 20.0, 6.0);
    c.circle((220.0, 100.0), 40.0);
    c.filled_disc((40.0, 110.0), 6.0);
    c
}

#[test]
fn vectorize_recovers_lines_dashes_circle_and_ignores_blob() {
    let ink = drawing().ink();
    let strokes = vectorize(&ink, 8.0);

    let a = find_line(&strokes, (20.0, 20.0), (220.0, 20.0), 1.5).expect("line A");
    assert_eq!(a.pattern, Pattern::Continuous);
    assert!(
        a.support > 0.95 && (0.5..=2.0).contains(&a.width_px),
        "{a:?}"
    );
    let b = find_line(&strokes, (30.0, 40.0), (130.0, 150.0), 1.5).expect("line B");
    assert_eq!(b.pattern, Pattern::Continuous);
    assert!(b.support > 0.95, "{b:?}");

    let found_arcs = arcs(&strokes);
    assert_eq!(found_arcs.len(), 1, "arcs: {found_arcs:?}");
    let Primitive::Arc {
        c, r, sweep_rad, ..
    } = found_arcs[0].primitive
    else {
        unreachable!()
    };
    assert!((r - 40.0).abs() < 0.4, "r = {r}");
    assert!(dist(c, (220.0, 100.0)) < 1.0, "c = {c:?}");
    assert!((sweep_rad.abs() - TAU).abs() < 0.05, "sweep = {sweep_rad}");
    assert!(found_arcs[0].support > 0.95);

    let dashes: Vec<&Stroke> = strokes
        .iter()
        .filter(|s| match s.primitive {
            Primitive::Line { p, q } => (p.1 - 190.0).abs() < 1.5 && (q.1 - 190.0).abs() < 1.5,
            Primitive::Arc { .. } => false,
        })
        .collect();
    assert!(dashes.len() >= 8, "dashes: {}", dashes.len());
    assert!(
        dashes.iter().all(|s| s.pattern == Pattern::Dashed),
        "{dashes:?}"
    );

    // The blob yields nothing of length >= 8 px.
    for s in &strokes {
        let m = s.primitive.mid();
        assert!(
            dist(m, (40.0, 110.0)) > 12.0 || s.primitive.length() < 8.0,
            "blob stroke {s:?}"
        );
    }

    let merged = merge_collinear(strokes, 3f64.to_radians(), 2.0, 10.0);
    let dashed =
        find_line(&merged, (20.0, 190.0), (274.0, 190.0), 1.5).expect("merged dashed line");
    assert_eq!(dashed.pattern, Pattern::Dashed);
    assert!(
        dashed.support > 0.5 && dashed.support < 0.95,
        "merged support = {}",
        dashed.support
    );
    assert_eq!(
        merged
            .iter()
            .filter(
                |s| matches!(s.primitive, Primitive::Line { p, .. } if (p.1 - 190.0).abs() < 1.5)
            )
            .count(),
        1
    );
    assert!(find_line(&merged, (20.0, 20.0), (220.0, 20.0), 1.5).is_some());
    assert_eq!(arcs(&merged).len(), 1);
}

#[test]
fn erase_removes_stroke_from_vectorisation() {
    let mut ink = drawing().ink();
    assert!(find_line(&vectorize(&ink, 8.0), (20.0, 20.0), (220.0, 20.0), 1.5).is_some());
    erase(&mut ink, &[((20.0, 20.0), (220.0, 20.0), 1.0)], &[]);
    let strokes = vectorize(&ink, 8.0);
    assert!(find_line(&strokes, (20.0, 20.0), (220.0, 20.0), 1.5).is_none());
    assert!(find_line(&strokes, (30.0, 40.0), (130.0, 150.0), 1.5).is_some());
    assert_eq!(arcs(&strokes).len(), 1);
}

#[test]
fn crossing_lines_come_back_whole_after_merge() {
    let mut c = Canvas::new(100, 100);
    c.line(10, 50, 90, 50);
    c.line(50, 10, 50, 90);
    let ink = c.ink();
    let strokes = vectorize(&ink, 5.0);
    assert_eq!(strokes.len(), 4, "{strokes:?}");
    let merged = merge_collinear(strokes, 2f64.to_radians(), 1.5, 3.0);
    assert_eq!(merged.len(), 2, "{merged:?}");
    assert!(find_line(&merged, (10.0, 50.0), (90.0, 50.0), 1.0).is_some());
    assert!(find_line(&merged, (50.0, 10.0), (50.0, 90.0), 1.0).is_some());
}

#[test]
fn vectorize_measures_thick_stroke_width_and_extent() {
    let mut c = Canvas::new(200, 100);
    c.thick_line((20.0, 50.0), (180.0, 50.0), 3.0);
    let ink = c.ink();
    let strokes = vectorize(&ink, 10.0);
    let s = find_line(&strokes, (20.0, 50.0), (180.0, 50.0), 1.0).expect("thick line");
    assert!((2.5..=3.5).contains(&s.width_px), "width = {}", s.width_px);
    assert_eq!(s.pattern, Pattern::Continuous);
}

#[test]
fn vectorize_dash_dot_centre_line() {
    let mut c = Canvas::new(400, 60);
    // Long dash 30, gap 5, dot 3, gap 5 ...
    let mut x = 10i64;
    while x < 380 {
        c.line(x, 30, (x + 30).min(389), 30);
        x += 35;
        if x + 3 <= 389 {
            c.line(x, 30, x + 3, 30);
        }
        x += 8;
    }
    let ink = c.ink();
    let strokes = vectorize(&ink, 8.0);
    let on_line: Vec<&Stroke> = strokes
        .iter()
        .filter(|s| matches!(s.primitive, Primitive::Line { p, .. } if (p.1 - 30.0).abs() < 1.0))
        .collect();
    assert!(on_line.len() >= 10, "{}", on_line.len());
    assert!(
        on_line.iter().all(|s| s.pattern == Pattern::DashDot),
        "{on_line:?}"
    );
    // Dots (3 px) survive the 8-px minimum length because they belong to the run.
    assert!(on_line.iter().any(|s| s.primitive.length() < 8.0));
    let merged = merge_collinear(strokes, 2f64.to_radians(), 1.5, 8.0);
    let line = merged
        .iter()
        .find(|s| matches!(s.primitive, Primitive::Line { p, .. } if (p.1 - 30.0).abs() < 1.0))
        .expect("merged");
    assert_eq!(line.pattern, Pattern::DashDot);
}

#[test]
fn calibrate_scale_rejects_one_outlier_in_six() {
    let noise = [0.2, -0.3, 0.1, -0.2, 0.3, -0.1];
    let nominal = [10.0, 25.0, 40.0, 60.0, 80.0, 100.0];
    let mut samples: Vec<(f64, f64)> = nominal
        .iter()
        .zip(noise)
        .map(|(&n, e)| (n, 4.0 * n + e))
        .collect();
    samples[3].1 = 300.0; // misread dimension: should be 240
    let (scale, residual) = calibrate_scale(&samples).expect("scale");
    assert!((scale - 4.0).abs() < 0.02, "scale = {scale}");
    assert!(residual < 0.01, "residual = {residual}");
}

#[test]
fn png_round_trip_grey_and_rgb() {
    let mut c = Canvas::new(37, 23);
    c.line(2, 3, 30, 19);
    c.circle((20.0, 11.0), 7.0);
    let mask = c.m.clone();

    let mut grey = Vec::new();
    {
        let mut enc = png::Encoder::new(&mut grey, 37, 23);
        enc.set_color(png::ColorType::Grayscale);
        enc.set_depth(png::BitDepth::Eight);
        let mut w = enc.write_header().unwrap();
        let data: Vec<u8> = mask.iter().map(|&d| if d { 30 } else { 240 }).collect();
        w.write_image_data(&data).unwrap();
    }
    let ink = Ink::from_png(&grey, 128).unwrap();
    assert_eq!((ink.width, ink.height), (37, 23));
    assert_eq!(ink.mask(), &mask[..]);
    assert_eq!(ink.dark_count(), mask.iter().filter(|&&d| d).count());

    let mut rgba = Vec::new();
    {
        let mut enc = png::Encoder::new(&mut rgba, 37, 23);
        enc.set_color(png::ColorType::Rgba);
        enc.set_depth(png::BitDepth::Eight);
        let mut w = enc.write_header().unwrap();
        let mut data = Vec::new();
        for &d in &mask {
            // Ink is dark blue; paper is fully transparent (composited over white).
            data.extend_from_slice(if d { &[20, 20, 90, 255] } else { &[0, 0, 0, 0] });
        }
        w.write_image_data(&data).unwrap();
    }
    let ink = Ink::from_png(&rgba, 128).unwrap();
    assert_eq!(ink.mask(), &mask[..]);
    assert!(Ink::from_png(b"not a png", 128).is_err());
}
